const $=id=>document.getElementById(id),tabs=[...document.querySelectorAll('.tab')],overview=$('overview'),plannerPage=$('plannerPage'),insightsPage=$('insightsPage'),settings=$('settings'),notice=$('notice');let cfg,lastOverview=null,planPage=1,planPageSize=25,currentPage='overview';
const time24=value=>new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(value);
const time24Seconds=value=>new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(value);
const planPrice=(value,kind,slotStart='')=>value==null?'—':`<button type="button" class="slot-price price-breakdown-trigger ${Number(value)<0?'negative-price':''}" data-price-kind="${esc(kind)}" data-price-slot="${esc(slotStart)}" aria-haspopup="true" aria-expanded="false" title="Show ${esc(kind)} price calculation">${Number(value).toFixed(2)} c/kWh</button>`;
function showPage(page){currentPage=page;tabs.forEach(x=>x.classList.toggle('active',x.dataset.tab===page));overview.classList.toggle('hidden',page!=='overview');plannerPage.classList.toggle('hidden',page!=='plannerPage');insightsPage.classList.toggle('hidden',page!=='insightsPage');settings.classList.toggle('hidden',page!=='settings');if(page==='plannerPage')renderPlannerPage();if(page==='insightsPage')loadInsights();enhancePlannerSelectionCount()}
tabs.forEach(t=>t.onclick=()=>showPage(t.dataset.tab));
$('plannerCard').onclick=event=>{if(event.target.closest('[data-explain],.price-breakdown-trigger'))return;showPage('plannerPage')};$('plannerCard').onkeydown=event=>{if((event.key==='Enter'||event.key===' ')&&!event.target.closest('[data-explain],.price-breakdown-trigger')){event.preventDefault();showPage('plannerPage')}};
const fmt=(f,d=1)=>f&&f.value!=null?`${Number(f.value).toFixed(d)} ${f.unit}`:'—';
const power=f=>{if(!f||f.value==null)return'—';const kw=Math.abs(Number(f.value)),w=kw*1000;return w<1000?`${Math.round(w)} W`:`${kw.toFixed(2)} kW`};
const temperature=f=>f&&f.value!=null?`${Number(f.value).toFixed(0)}°C (${f.status||'Normal'})`:'Temperature unavailable';
function setTemperature(id,field){const el=$(id);el.textContent=temperature(field);const status=String(field?.status||'').toLowerCase();el.className='temperature '+(status==='high'?'high':status==='warm'?'warm':'')}
const titleCase=s=>String(s||'unknown').replaceAll('_',' ').replace(/\b\w/g,x=>x.toUpperCase());
function dot(id,status){$(id).className='dot '+(status==='ok'?'':status==='degraded'?'warn':'bad')}
async function loadConfig(){const r=await fetch('api/config');cfg=await r.json();const t=cfg.energy_tariff,f=cfg.forecast_connector||{};$('siteName').value=cfg.site.name;$('siteLabel').textContent=cfg.site.name+' energy intelligence';$('timezone').value=cfg.site.timezone;$('country').value=cfg.site.country;$('currency').value=cfg.site.currency;$('horizon').value=cfg.planning.horizon_hours;$('strategy').value=cfg.planning.strategy;$('minimumSellProfit').value=cfg.planning.minimum_sell_profit_cents_kwh??2;$('minimumHorizonGain').value=cfg.planning.minimum_horizon_gain_eur??0.5;$('mode').value=cfg.runtime.mode;$('modeBadge').textContent=titleCase(cfg.runtime.mode);$('maxImport').value=cfg.grid_policy.max_import_kw;$('maxExport').value=cfg.grid_policy.max_export_kw;$('minSoc').value=cfg.battery_policy.min_operational_soc_percent;$('reserveSoc').value=cfg.battery_policy.reserve_soc_percent;$('maxSoc').value=cfg.battery_policy.max_planned_soc_percent;$('maxCharge').value=cfg.battery_policy.max_charge_kw;$('maxDischarge').value=cfg.battery_policy.max_discharge_kw;$('batteryEfficiency').value=cfg.battery_policy.roundtrip_efficiency_percent;$('degradationCost').value=cfg.battery_policy.degradation_cost_cents_kwh;$('weatherEntity').value=f.weather_entity||'';$('solarPeakKw').value=f.solar_peak_kw??25.48;$('solarTilt').value=f.solar_tilt_degrees??22;$('solarAzimuth').value=f.solar_azimuth_degrees??180;$('pvForecastEntity').value=f.pv_forecast_entity||'';$('loadForecastEntity').value=f.load_forecast_entity||'';$('fallbackLoad').value=f.fallback_load_kw??'';$('capacityEntity').value=cfg.battery_connector.capacity_entity;$('socEntity').value=cfg.battery_connector.soc_entity;$('powerEntity').value=cfg.battery_connector.power_entity;$('pvEntity').value=cfg.power_connector.pv_power_entity;$('loadEntity').value=cfg.power_connector.load_power_entity;$('gridEntity').value=cfg.power_connector.grid_power_entity;$('staleAfter').value=cfg.power_connector.stale_after_seconds;$('priceEntity').value=cfg.price_connector.entity;$('priceUnit').value=cfg.price_connector.price_unit;$('sourceIncludesVat').checked=cfg.price_connector.source_includes_vat;$('includeVat').checked=cfg.price_connector.include_vat;$('vatPercent').value=cfg.price_connector.vat_percent;$('importMargin').value=t.import_margin_cents_kwh;$('exportMargin').value=t.export_margin_cents_kwh;$('electricityExcise').value=t.electricity_excise_cents_kwh;$('renewableFee').value=t.renewable_fee_cents_kwh;$('securityFee').value=t.security_of_supply_fee_cents_kwh;$('importBalancingCost').value=t.import_balancing_cost_cents_kwh;$('exportBalancingCost').value=t.export_balancing_cost_cents_kwh;$('gridWeekdayDay').value=t.grid_weekday_day_cents_kwh;$('gridWeekdayNight').value=t.grid_weekday_night_cents_kwh;$('gridWeekendHoliday').value=t.grid_weekend_holiday_cents_kwh;$('gridDayStart').value=t.grid_day_start_hour;$('gridDayEnd').value=t.grid_day_end_hour;$('holidayDates').value=(t.holiday_dates||[]).join(', ');$('renewableSupportEnabled').checked=t.renewable_support_enabled;$('renewableSupport').value=t.renewable_support_cents_kwh;$('manualToggle').checked=cfg.battery_connector.capacity_source==='manual_override';$('manualCapacity').value=cfg.battery_connector.manual_capacity_kwh??'';toggleManual()}
const behaviorProfiles={
 value_first:{label:'Value First',buffer:2,confidence:55,curtailment:12,wear:1,summary:'Targets the configured reserve + 2% before the next reliable solar window and values forecast battery headroom highly.'},
 balanced:{label:'Balanced',buffer:7,confidence:70,curtailment:8,wear:1.15,summary:'Keeps a 7% pre-solar safety buffer and requires a reasonably confident PV forecast before releasing forecast-displaced energy.'},
 resilience_first:{label:'Resilience First',buffer:20,confidence:80,curtailment:3,wear:1.5,summary:'Keeps a 20% pre-solar safety buffer, values battery wear more strongly and requires a high-confidence forecast.'}
};
function selectedBehavior(){return document.querySelector('input[name="behaviorProfile"]:checked')?.value||'balanced'}
function renderBehaviorSettings(){const key=selectedBehavior(),custom=key==='custom',p=custom?{label:'Custom',buffer:Number($('customSolarBuffer').value||0),confidence:Number($('customForecastConfidence').value||0),curtailment:Number($('customCurtailmentPenalty').value||0),wear:Number($('customWearMultiplier').value||1),summary:'Uses your explicit Planner objective weights.'}:behaviorProfiles[key];$('customBehavior').classList.toggle('hidden',!custom);$('behaviorSummary').innerHTML=`<div class="detected-row"><span>Selected behavior</span><strong>${esc(p.label)}</strong></div><div class="source">${esc(p.summary)}</div><div class="source">Pre-solar buffer ${p.buffer}% · PV confidence ${p.confidence}% · curtailment cost ${p.curtailment} c/kWh · wear importance ${p.wear}×</div>`}
const loadConfigBase=loadConfig;
loadConfig=async function(){await loadConfigBase();const p=cfg.planning||{},profile=p.behavior_profile||'balanced',radio=document.querySelector(`input[name="behaviorProfile"][value="${profile}"]`);if(radio)radio.checked=true;$('customSolarBuffer').value=p.custom_solar_buffer_percent??7;$('customForecastConfidence').value=p.custom_min_forecast_confidence_percent??70;$('customCurtailmentPenalty').value=p.custom_curtailment_penalty_cents_kwh??8;$('customWearMultiplier').value=p.custom_wear_cost_multiplier??1.15;renderBehaviorSettings()}
document.querySelectorAll('input[name="behaviorProfile"]').forEach(input=>input.addEventListener('change',renderBehaviorSettings));['customSolarBuffer','customForecastConfidence','customCurtailmentPenalty','customWearMultiplier'].forEach(id=>$(id).addEventListener('input',renderBehaviorSettings));
