function setRefreshFailed(failed){const status=$('freshness').closest('button');status.classList.toggle('refresh-failed',failed);status.setAttribute('aria-label',failed?'Live data refresh failed. Open update details.':'Live data status and last update')}
function resetRoutes(){document.querySelectorAll('.energy-route').forEach(route=>{route.classList.remove('active','reverse');route.style.removeProperty('--flow-opacity');route.style.removeProperty('--flow-speed')})}
function applyRoutes(routes,balanceKw=0){resetRoutes();const active=(Array.isArray(routes)?routes:[]).filter(r=>Number(r.power_kw)>=0.02),components=new Map(),chips=[];for(const r of active){const key=`${r.from}>${r.to}`,links=routeMap[key],powerKw=Number(r.power_kw)||0;if(links)links.forEach(([id,reverse])=>{const current=components.get(id)||{power:0,reverse};current.power+=powerKw;current.reverse=reverse;components.set(id,current)});const from=routeLabel[r.from]||titleCase(r.from),to=routeLabel[r.to]||titleCase(r.to);chips.push(`<span class="route-chip"><strong>${from} → ${to}</strong> ${r.power_kw<1?Math.round(r.power_kw*1000)+' W':Number(r.power_kw).toFixed(2)+' kW'}</span>`)}components.forEach(({power,reverse},id)=>{const route=document.querySelector(`[data-energy-route="${id}"]`);if(!route)return;const strength=Math.min(1,.52+Math.log10(1+power)*.34),speed=Math.max(1.8,4.8-Math.log10(1+power)*1.55);route.classList.add('active');route.classList.toggle('reverse',reverse);route.style.setProperty('--flow-opacity',strength.toFixed(2));route.style.setProperty('--flow-speed',`${speed.toFixed(2)}s`)});const difference=Math.abs(Number(balanceKw)||0);if(difference>=.02){const label=Number(balanceKw)>0?'Unallocated input':'Unallocated demand';chips.push(`<span class="route-chip balance-warning" title="Live meters can update at different times and may use different AC/DC measurement points. This difference is not assigned to a physical route."><strong>${label}</strong> ${difference<1?Math.round(difference*1000)+' W':difference.toFixed(2)+' kW'}</span>`)}$('flowRoutes').innerHTML=chips.length?chips.join(''):'<span class="route-chip">No active flow above 20 W</span>';return active.length}
function currentPlannerSlot(o){const slots=o?.price?.slots||[];return slots.find(slot=>slot.is_current)||slots.find(slot=>{const start=new Date(slot.start),end=slot.end?new Date(slot.end):new Date(start.getTime()+15*60000),now=Date.now();return start.getTime()<=now&&now<end.getTime()})||slots[0]||null}
function renderOverviewPlanner(o){const slot=currentPlannerSlot(o),planner=o.planner||{};$('plannerImportPrice').textContent=`→ ${slot?.import_cents_kwh==null?'—':Number(slot.import_cents_kwh).toFixed(2)+' c/kWh'}`;$('plannerExportPrice').textContent=`← ${slot?.export_cents_kwh==null?'—':Number(slot.export_cents_kwh).toFixed(2)+' c/kWh'}`;$('plannerImportPrice').classList.toggle('negative-price',Number(slot?.import_cents_kwh)<0);$('plannerExportPrice').classList.toggle('negative-price',Number(slot?.export_cents_kwh)<0);if(!slot){$('plannerSlotTime').textContent='Current slot unavailable';$('plannerSlotRemaining').textContent='—';$('plannerSlotProgress').style.width='0%';$('plannerNetResult').textContent='Net slot result —';$('plannerEconomicsDetail').textContent='Revenue and battery wear unavailable';return}const start=new Date(slot.start),end=slot.end?new Date(slot.end):new Date(start.getTime()+15*60000),progress=slot.progress_percent==null?Math.max(0,Math.min(100,(Date.now()-start.getTime())/(end.getTime()-start.getTime())*100)):Number(slot.progress_percent),remaining=slot.remaining_minutes==null?Math.max(0,(end.getTime()-Date.now())/60000):Number(slot.remaining_minutes),cashFlow=-Number(slot.slot_cash_cost_cents||0),wear=Number(slot.slot_wear_cost_cents||0),net=cashFlow-wear,reason=slot.action_reason||planner.reason||'Planner is building the current slot context.';$('plannerSlotTime').textContent=`${time24(start)} – ${time24(end)}`;$('plannerSlotRemaining').textContent=remaining<=0?'Ending now':`${Math.ceil(remaining)} min left`;$('plannerSlotProgress').style.width=`${progress.toFixed(1)}%`;$('plannerAction').textContent=slot.action||planner.action||'OBSERVE';$('plannerReason').textContent=/projected soc/i.test(reason)?reason:`${reason} Projected SOC ${Number(slot.soc_before_percent??0).toFixed(0)}% → ${Number(slot.soc_after_percent??0).toFixed(0)}%.`;$('plannerNetResult').textContent=`Net slot result ${signedMoneyFromCents(net)}`;const cashLabel=cashFlow>=0?'Revenue':'Energy cost',cashValue=cashFlow>=0?signedMoneyFromCents(cashFlow):`−${moneyFromCents(Math.abs(cashFlow))}`,wearValue=wear>0?`−${preciseWearFromCents(wear)}`:'0.00 €';$('plannerEconomicsDetail').textContent=`${cashLabel} ${cashValue} · Battery wear ${wearValue}`}
async function loadOverview(){const r=await fetch('api/overview');if(!r.ok)throw Error('Overview unavailable');const o=await r.json();lastOverview=o;setRefreshFailed(false);const s=o.state,b=s.battery,f=s.flow,p=o.planner,m=o.metrics;$('versionLabel').textContent=o.version;$('pvPower').textContent=power(s.pv.power_kw);$('loadPower').textContent=power(s.load.power_kw);$('gridPower').textContent=power(s.grid.power_kw);$('batteryPower').textContent=power(b.power_kw);$('batterySoc').textContent=b.soc_pct.value==null?'—':`${b.soc_pct.value.toFixed(0)}%`;$('pvState').textContent=titleCase(f.pv);$('gridState').textContent=titleCase(f.grid);$('batteryState').textContent=titleCase(f.battery);setTemperature('batteryTemperature',b.temperature_c);setTemperature('inverterTemperature',s.inverter?.temperature_c);$('energyStored').textContent=b.energy_kwh.value==null?'— stored':`${b.energy_kwh.value.toFixed(1)} kWh stored`;const activeCapacity=b.capacity_kwh.value,capacitySource=b.capacity_kwh.source||'capacity sensor';$('detectedCapacity').textContent=activeCapacity==null?'Unavailable':`${Number(activeCapacity).toFixed(2)} kWh`;$('detectedCapacityStatus').textContent=activeCapacity==null?`${capacitySource} is unavailable`:capacitySource==='manual_override'?'Configured by manual override':`Detected from ${capacitySource}`;$('flowHeadline').textContent=f.summary;$('plannerAction').textContent=p.action;$('plannerReason').textContent=p.reason;$('confidenceValue').textContent=`${p.confidence}%`;$('confidenceBar').style.width=`${p.confidence}%`;$('plannerCard').dataset.tone=p.tone;$('executionMode').textContent=p.execution;$('autonomyValue').textContent=`${m.autonomy_percent.toFixed(0)}%`;$('gridDependency').textContent=`${m.grid_dependency_percent.toFixed(0)}% grid`;$('sharePv').style.width=`${m.home_supply_percent.pv}%`;$('shareBattery').style.width=`${m.home_supply_percent.battery}%`;$('shareGrid').style.width=`${m.home_supply_percent.grid}%`;$('sharePvValue').textContent=`${m.home_supply_percent.pv.toFixed(0)}%`;$('shareBatteryValue').textContent=`${m.home_supply_percent.battery.toFixed(0)}%`;$('shareGridValue').textContent=`${m.home_supply_percent.grid.toFixed(0)}%`;$('strategyValue').textContent=p.behavior_label||titleCase(p.behavior_profile||'balanced');$('systemState').textContent=s.health.status==='ok'?'Healthy':s.health.status==='degraded'?'Limited':'Unavailable';const connectorIssues=(s.health.critical_missing||[]).length+(s.health.critical_stale||[]).length;$('connectorState').textContent=connectorIssues?'Needs attention':'Connected';dot('systemDot',s.health.status);dot('connectorDot',connectorIssues?'degraded':'ok');const observed=new Date(o.observed_at),ageSec=Math.max(0,Math.round((Date.now()-observed.getTime())/1000)),relativeAge=ageSec<5?'Just now':`${ageSec} s ago`;$('freshness').textContent='Live';$('freshness').dataset.relative=relativeAge;$('freshness').closest('button').title=`Updated ${relativeAge.toLowerCase()} · ${observed.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'})}`;applyRoutes(f.routes,f.balance_kw);[['solarNode',f.pv==='producing'],['gridNode',!['idle','unknown'].includes(f.grid)],['homeNode',f.load==='consuming'],['batteryNode',!['idle','unknown'].includes(f.battery)]].forEach(([id,on])=>$(id).classList.toggle('active',on));const marketPrice=$('marketPrice'),marketRank=$('marketRank'),marketSource=$('marketSource');if(marketPrice)marketPrice.textContent=o.price.current_cents_kwh==null?'—':`${o.price.current_cents_kwh.toFixed(2)} c/kWh`;if(marketRank)marketRank.textContent=o.price.slot_count?`Rank ${o.price.rank_high_to_low||'—'} of ${o.price.slot_count} · ${o.price.percentile==null?'—':Number(o.price.percentile).toFixed(0)} percentile`:'No horizon prices available';if(marketSource)marketSource.textContent=o.price.available?`Source: ${o.price.entity_id} · ${o.price.current_source||'unknown'}${o.price.connector_mode==='auto_discovered'?' · auto-discovered':''}`:`Price unavailable · configured: ${o.price.configured_entity_id}${o.price.error?' · '+o.price.error:''}`;const solar=o.price.plan?.pv_forecast;if($('solarForecastStatus'))$('solarForecastStatus').textContent=solar?.available?'Connected':'Unavailable';if($('solarForecastDetail'))$('solarForecastDetail').textContent=solar?.available?(solar.mode==='weather_adjusted'?`Automatic · ${solar.weather_entity||'HA weather'} · ${solar.points||0} slots · avg cloud ${solar.average_cloud_coverage??'—'}%`:`Fallback entity · ${solar.entity_id||'configured source'}`):(solar?.error||'No hourly Home Assistant weather forecast available')}

const explainCopy={
state:{eyebrow:'System health',title:'State engine',text:'The state engine validates live Home Assistant measurements and builds the shared energy snapshot used by the planner, autonomy calculation and power-flow routes.'},
connectors:{eyebrow:'System health',title:'Connectors',text:'Connector diagnostics show whether each configured Home Assistant entity is available and fresh. A valid zero reading is data, not a fault.'},
strategy:{eyebrow:'Planner behavior',title:'Planner behavior',text:'The behavior profile controls reserve, forecast confidence, battery-wear weighting and how strongly Planner creates room for incoming solar.'},
planner:{eyebrow:'Planner',title:'Current recommendation',text:'This recommendation combines live energy flow, battery reserve, market price position and measurement quality.'},
confidence:{eyebrow:'Planner',title:'Decision confidence',text:'Confidence is a data-quality score capped by the certainty of the current planning rule. Missing, stale or unavailable market data reduces it.'},
autonomy:{eyebrow:'Energy balance',title:'Home autonomy',text:'Home autonomy is the share of current home demand supplied by solar and battery rather than imported from the grid.'},
stored:{eyebrow:'Battery',title:'Stored energy',text:'Stored energy is the estimated energy currently available in the battery.'},
capacity:{eyebrow:'Battery',title:'Usable capacity',text:'Usable capacity is the battery capacity Energy Pilot uses for energy calculations. It comes from the configured capacity sensor or a manual override.'},
soc:{eyebrow:'Battery',title:'Battery state of charge',text:'SOC is the battery charge level reported by the configured Home Assistant entity.'},
routes:{eyebrow:'Live energy',title:'Active routes',text:'Routes are reconciled energy-flow estimates above 20 W. They explain which sources are currently supplying the home, battery or grid.'},
updated:{eyebrow:'System health',title:'Last successful update',text:'This is when Energy Pilot last completed a successful overview refresh using the latest available Home Assistant data.'},
qilowatt:{eyebrow:'External dispatch',title:'Qilowatt',text:'Qilowatt can remain the command authority while Energy Pilot monitors its desired mode, source, connection and power limit without competing for inverter control.'}
};
const fieldNames={
'battery.capacity_kwh':'Battery capacity','battery.soc_pct':'Battery SOC','battery.power_kw':'Battery power','pv.power_kw':'Solar production','load.power_kw':'Home load','grid.power_kw':'Grid power'
};
function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function ageLabel(sec){if(sec==null)return 'Update time unavailable';if(sec<5)return 'Updated just now';if(sec<60)return `Updated ${Math.round(sec)} seconds ago`;if(sec<3600)return `Updated ${Math.round(sec/60)} minutes ago`;return `Updated ${Math.round(sec/3600)} hours ago`}
function row(label,value,meta=''){return `<div class="detail-row"><span>${esc(label)}</span><div>${value}${meta?`<small>${esc(meta)}</small>`:''}</div></div>`}
function calcValue(value){return value==null?'—':`${Number(value)>=0?'+':''}${Number(value).toFixed(5)} c/kWh`}
const actionDescriptions={
'NORMAL':'The inverter balances solar, home consumption, grid and battery automatically. Solar covers the home first, then charges the battery, and remaining surplus may be exported within the configured limit.',
'BUY':'Charge the battery from the grid. Forecast solar supplies forecast home demand first; the grid supplies any remaining home demand and the explicitly shown battery-charging power.',
'SELL':'Discharge the battery to sell energy to the grid. Solar output is sold first where supported, with battery energy supplying export and home consumption as needed.',
'SAVE BATTERY':'Do not discharge the battery. Buy the home’s energy from the grid so stored energy remains available for later consumption or a stronger selling window.',
'LIMIT EXPORT':'Restrict grid export to avoid unprofitable selling, especially during negative-price periods. The inverter may need to reduce solar production or export.',
'PV SELL':'Sell only solar surplus, without discharging the battery. Solar covers home consumption first and remaining production is exported within the configured limit.'
};
function actionTone(action){return action==='SELL'||action==='PV SELL'?'sell':action==='BUY'?'buy':action==='SAVE BATTERY'||action==='LIMIT EXPORT'?'protect':'normal'}
function actionMarkup(action,reason='',mobileMeta='',detail=''){const description=actionDescriptions[action]||actionDescriptions.NORMAL;return `<span class="action-wrap"><span class="plan-action ${actionTone(action)}">${esc(action)}</span><button class="action-info-button" type="button" aria-label="Explain ${esc(action)}" aria-expanded="false">i</button><span class="action-tooltip" role="tooltip"><strong>${esc(action)}</strong>${esc(description)}${reason?`<small>Why here: ${esc(reason)}</small>`:''}${detail?`<div class="mobile-slot-detail">${detail}</div>`:''}</span>${mobileMeta?`<span class="mobile-slot-meta">${mobileMeta}</span>`:''}</span>`}
function priceCalculation(o,kind,id){const price=o.price||{},c=price.components||{},items=kind==='import'?[
['Spot price',c.spot],['Import margin',c.import_margin],['Electricity excise',c.electricity_excise],['Renewable-energy fee',c.renewable_fee],['Security-of-supply fee',c.security_of_supply_fee],['Import balancing cost',c.import_balancing_cost],['Grid fee',c.grid_fee],['VAT',c.vat]
]:[
['Spot price',c.spot],['Export margin',c.export_margin],['Export balancing cost',c.export_balancing_cost],['VAT on balancing cost',c.export_balancing_vat],['Renewable support',c.renewable_support]
];const total=kind==='import'?price.import_cents_kwh:price.export_cents_kwh,slot=price.active_slot_start?time24(new Date(price.active_slot_start)):null,reported=price.reported_current_spot_cents_kwh;return `<div id="${esc(id)}" class="price-popover" role="region" aria-label="${esc(titleCase(kind))} price calculation"><div class="price-calc-title">${esc(titleCase(kind))} price calculation</div>${items.map(([label,value])=>`<div class="price-calc-row"><span>${esc(label)}</span><strong>${calcValue(value)}</strong></div>`).join('')}<div class="price-calc-row price-calc-total"><span>Effective ${esc(kind)} price</span><strong>${total==null?'—':Number(total).toFixed(5)+' c/kWh'}</strong></div><div class="price-calc-note">Source: ${esc(price.current_source||'unavailable')}${slot?' · active slot '+esc(slot):''} · VAT rate: ${Number(price.vat_percent||0).toFixed(2)}%${price.source_vat_included?' · source spot price already includes VAT':''}${reported!=null&&price.current_source==='active_slot'?' · sensor state '+Number(reported).toFixed(5)+' c/kWh':''}</div></div>`}
