function moneyFromCents(value){return `${(Number(value||0)/100).toFixed(2)} €`}
function preciseWearFromCents(value){const amount=Math.abs(Number(value||0));return amount>0&&amount<1?`${amount.toFixed(amount<0.1?3:2)} c`:moneyFromCents(amount)}
function signedMoneyFromCents(value){const amount=Number(value||0);return `${amount>0?'+':amount<0?'−':''}${moneyFromCents(Math.abs(amount))}`}
function cashFlowFromCostCents(value){return -Number(value||0)}
function expenseMoneyFromCents(value){const amount=Math.abs(Number(value||0));return amount>0?`−${moneyFromCents(amount)}`:moneyFromCents(0)}
function invoiceMoneyFromCents(value){const cashResult=Number(value||0),invoiceBalance=Math.abs(cashResult)<.005?0:-cashResult;return signedMoneyFromCents(invoiceBalance)}
function slotEconomicsText(slot){
 const cashFlow=-Number(slot.slot_cash_cost_cents||0),wear=Number(slot.slot_wear_cost_cents||0),net=cashFlow-wear;
 const cashLabel=cashFlow>=0?'Revenue':'Energy cost',wearText=wear>0?`−${preciseWearFromCents(wear)}`:'not included';
 return `${cashLabel} ${signedMoneyFromCents(cashFlow)} · Battery wear ${wearText} · Net slot result ${signedMoneyFromCents(net)}`;
}
function slotEconomicsTitle(slot){
 const wearRate=Number(slot.wear_rate_cents_kwh||0);
 return wearRate>0
  ?`Revenue or energy cost is the slot cash flow before wear. Battery wear uses the configured ${wearRate.toFixed(2)} c/kWh rate. Net slot result is cash flow minus battery wear.`
  :'Battery wear cost is 0 c/kWh in Settings, so wear is not included in the net slot result.';
}
