function insightPeriodLabel(data){const start=new Date(data.period_start),end=new Date(new Date(data.period_end).getTime()-1000);if(data.period==='lifetime')return 'All tracked data';const options={day:'2-digit',month:'short',year:'numeric'};return `${start.toLocaleDateString([],options)} – ${end.toLocaleDateString([],options)}`}
function renderInsightsChart(data){const root=$('insightsChart'),series=data.series||[];if(!series.length){root.innerHTML='<div class="chart-empty">No measured energy in this period yet.</div>';return}const width=1000,height=330,left=54,right=20,top=24,bottom=54,plotW=width-left-right,plotH=height-top-bottom,max=Math.max(1,...series.flatMap(row=>['pv_kwh','load_kwh','grid_import_kwh','grid_export_kwh'].map(key=>Number(row[key]||0)))),groupW=plotW/series.length,barW=Math.max(2,Math.min(18,groupW*.17)),colors={pv_kwh:'#ffb54a',load_kwh:'#f5f8fb',grid_import_kwh:'#57aef0',grid_export_kwh:'#65df9a'},keys=['pv_kwh','load_kwh','grid_import_kwh','grid_export_kwh'];let bars='',labels='',grid='';for(let i=0;i<=4;i++){const y=top+plotH*i/4,value=max*(1-i/4);grid+=`<line x1="${left}" y1="${y}" x2="${width-right}" y2="${y}"/><text x="${left-10}" y="${y+4}" text-anchor="end">${value.toFixed(value<10?1:0)}</text>`}series.forEach((row,index)=>{const center=left+groupW*(index+.5);keys.forEach((key,k)=>{const value=Number(row[key]||0),h=value/max*plotH,x=center+(k-1.5)*barW,y=top+plotH-h;bars+=`<rect class="insights-bar insights-bar-${key}" x="${x.toFixed(2)}" y="${y.toFixed(2)}" width="${Math.max(1,barW-1).toFixed(2)}" height="${h.toFixed(2)}" rx="2" fill="${colors[key]}"><title>${row.period} · ${key.replaceAll('_',' ')} ${value.toFixed(2)} kWh</title></rect>`});if(series.length<=16||index%Math.ceil(series.length/12)===0){const label=data.aggregation==='month'?row.period.slice(5):new Date(row.period+'T12:00:00').toLocaleDateString([],{day:'2-digit',month:'short'});labels+=`<text x="${center}" y="${height-24}" text-anchor="middle">${esc(label)}</text>`}});root.innerHTML=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Measured energy history"><g class="insights-grid">${grid}</g><g>${bars}</g><g class="insights-axis">${labels}<text x="${left}" y="15">kWh</text></g></svg>`}
function renderInsights(data){insightsData=data;const t=data.totals,s=data.statement;$('insightsCoverage').textContent=`${data.data_quality.coverage_hours.toFixed(1)} h measured`;$('insightsBillResult').textContent=invoiceMoneyFromCents(t.bill_result_cents);$('insightsMetrics').innerHTML=insightMetric('PV production',`${Number(t.pv_kwh).toFixed(1)} kWh`,'Generated on site')+insightMetric('Home consumption',`${Number(t.load_kwh).toFixed(1)} kWh`,'Total measured load')+insightMetric('Self-consumed solar',`${Number(t.solar_self_consumed_kwh).toFixed(1)} kWh`,t.solar_self_consumption_percent==null?'Share unavailable':`${t.solar_self_consumption_percent}% of solar used directly`)+insightMetric('Grid import',`${Number(t.grid_import_kwh).toFixed(1)} kWh`,expenseMoneyFromCents(t.import_cost_cents))+insightMetric('Grid export',`${Number(t.grid_export_kwh).toFixed(1)} kWh`,signedMoneyFromCents(t.export_revenue_cents))+insightMetric('Self-sufficiency',t.self_sufficiency_percent==null?'—':`${t.self_sufficiency_percent}%`,'Home demand covered without grid import');$('statementPeriod').textContent=insightPeriodLabel(data);$('statementImport').textContent=expenseMoneyFromCents(s.import_cost_cents);$('statementExport').textContent=signedMoneyFromCents(s.export_revenue_cents);$('statementResult').textContent=invoiceMoneyFromCents(s.bill_result_cents);$('insightsWear').textContent=expenseMoneyFromCents(t.battery_wear_cents);$('insightsThroughput').textContent=`${Number(t.battery_throughput_kwh).toFixed(1)} kWh battery throughput`;$('insightsAfterWear').textContent=signedMoneyFromCents(t.result_after_wear_cents);$('insightsSince').textContent=new Date(data.tracking_since).toLocaleString([],{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});$('insightsLifetime').textContent=invoiceMoneyFromCents(data.lifetime.bill_result_cents);renderInsightsChart(data)}
async function loadInsights(){const custom=insightsPeriod==='custom',params=new URLSearchParams({period:insightsPeriod});if(custom){if(!$('insightsStart').value||!$('insightsEnd').value)return;params.set('start',$('insightsStart').value);params.set('end',$('insightsEnd').value)}$('insightsCoverage').textContent='Loading';try{const response=await fetch(`api/insights?${params}`,{cache:'no-store'}),data=await response.json();if(!response.ok)throw Error(data.detail||'Insights unavailable');renderInsights(data)}catch(error){$('insightsCoverage').textContent='Unavailable';$('insightsChart').innerHTML=`<div class="chart-empty">${esc(error.message)}</div>`}}
document.querySelectorAll('[data-insights-period]').forEach(button=>button.onclick=()=>{insightsPeriod=button.dataset.insightsPeriod;document.querySelectorAll('[data-insights-period]').forEach(item=>item.classList.toggle('active',item===button));$('insightsCustom').classList.toggle('hidden',insightsPeriod!=='custom');if(insightsPeriod!=='custom')loadInsights()});
$('insightsApply').onclick=loadInsights;
loadOverview=async function(){await loadOverviewCore();renderBenefits();const plan=lastOverview?.price?.plan||{},wear=plan.battery_wear;const cycle=lastOverview?.state?.battery?.cycle_count;if(cycle){const labels={configured:'Manual',auto_deye:'Automatic · Deye',auto_discovered:'Automatic'};$('batteryCycleSource').textContent=cycle.source?`${labels[cycle.connector_mode]||'Automatic'} · ${cycle.source}`:'Not detected'}if(!wear)return;const baseRate=Number(plan.battery_wear_base_rate_cents_kwh??wear.effective_rate_cents_kwh??0),effectiveRate=Number(plan.battery_wear_rate_cents_kwh??baseRate),multiplier=baseRate>0?effectiveRate/baseRate:1;$('batteryUsedCycles').textContent=wear.used_cycles==null?'Unavailable':Number(wear.used_cycles).toFixed(0);$('batteryRemainingCycles').textContent=wear.remaining_cycles==null?'Unavailable':Number(wear.remaining_cycles).toFixed(0);$('batteryBaseWear').textContent=`${baseRate.toFixed(5)} c/kWh`;$('batteryWearMultiplier').textContent=`×${multiplier.toFixed(2)}`;$('batteryEffectiveWear').textContent=`${effectiveRate.toFixed(5)} c/kWh`;$('batteryWearDetail').textContent=wear.mode==='automatic_remaining_life'?`Automatic base · ${Number(wear.system_cost_eur).toFixed(0)} € · ${Number(wear.capacity_kwh).toFixed(1)} kWh · ${wear.formula}`:`Manual fallback base · ${wear.error||'automatic inputs unavailable'}`}
const loadOverviewTimeCore=loadOverview;
loadOverview=async function(){await loadOverviewTimeCore();const observed=new Date(lastOverview.observed_at),relative=$('freshness').dataset.relative||'Just now';$('freshness').closest('button').title=`Updated ${relative.toLowerCase()} · ${time24Seconds(observed)}`;if(benefitPeriod==='month'&&lastOverview?.benefits_month){const month=lastOverview.benefits_month,since=new Date(month.tracking_since);$('benefitTotalDetail').textContent=`Estimated amount payable · negative means credit · tracking since ${since.toLocaleDateString([],{day:'2-digit',month:'short'})} ${time24(since)}`}const q=lastOverview?.qilowatt||{},status=q.status==='connected'?'Connected':q.status==='disabled'?'Off':q.status==='entities_missing'?'Not configured':'Disconnected';$('qilowattState').textContent=status;dot('qilowattDot',q.status==='connected'?'ok':q.status==='disabled'?'degraded':'unavailable');$('qilowattStatus').textContent=status;$('qilowattStatusDetail').textContent=q.status==='connected'?`${q.authority} · ${q.mode_raw||'no active mode'}${q.source_raw?' · '+q.source_raw:''}`:q.status==='disabled'?'Qilowatt is not connected.':`${q.entities_found||0} of 4 entities detected.`;if(currentPage==='plannerPage')renderPlannerPage();if(currentPage==='insightsPage')loadInsights()}
function renderOverviewPriceBreakdowns(o){const slot=currentPlannerSlot(o),key=slot?.start||'';$('plannerImportPrice').innerHTML=`→ ${planPrice(slot?.import_cents_kwh,'import',key)}`;$('plannerExportPrice').innerHTML=`← ${planPrice(slot?.export_cents_kwh,'export',key)}`;$('plannerImportPrice').classList.remove('negative-price');$('plannerExportPrice').classList.remove('negative-price')}
const loadOverviewPlannerCardCore=loadOverview;
loadOverview=async function(){await loadOverviewPlannerCardCore();renderOverviewPlanner(lastOverview);renderOverviewPriceBreakdowns(lastOverview)}
let settingsDirty=false;
function setSettingsDirty(dirty,message='Save to apply the new settings.'){settingsDirty=dirty;$('saveDock').classList.toggle('visible',dirty);$('saveDockTitle').textContent=dirty?'Unsaved changes':'Changes saved';$('saveDockText').textContent=message}
function setSaving(saving){$('save').disabled=saving;$('saveFloating').disabled=saving;$('discardFloating').disabled=saving;$('saveFloating').textContent=saving?'Saving…':'Save changes'}
async function saveConfiguration(){setSaving(true);notice.textContent='Saving…';$('saveDockTitle').textContent='Saving changes…';$('saveDockText').textContent='Applying the new configuration.';try{const r=await fetch('api/config',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload())});const d=await r.json();if(!r.ok){const error=d.detail||'Configuration is invalid.';notice.textContent=error;$('saveDockTitle').textContent='Could not save';$('saveDockText').textContent=error;return}notice.textContent='Configuration saved.';await loadConfig();await loadOverview();setSettingsDirty(false)}catch(e){notice.textContent=e.message;$('saveDockTitle').textContent='Could not save';$('saveDockText').textContent=e.message}finally{setSaving(false)}}
async function discardConfigurationChanges(){setSaving(true);$('saveDockTitle').textContent='Discarding changes…';$('saveDockText').textContent='Restoring the last saved configuration.';try{await loadConfig();setSettingsDirty(false);notice.textContent='Unsaved changes discarded.'}catch(e){notice.textContent=e.message;$('saveDockTitle').textContent='Could not discard';$('saveDockText').textContent=e.message}finally{setSaving(false)}}
$('settings').addEventListener('input',()=>setSettingsDirty(true));$('settings').addEventListener('change',()=>setSettingsDirty(true));$('save').onclick=saveConfiguration;$('saveFloating').onclick=saveConfiguration;$('discardFloating').onclick=discardConfigurationChanges;$('reset').onclick=async()=>{if(!confirm('Reset Energy Pilot configuration to defaults?'))return;await fetch('api/config/reset',{method:'POST'});await loadConfig();await loadOverview();setSettingsDirty(false)};
function showRefreshFailure(error){console.error('Overview refresh failed',error);setRefreshFailed(true);$('freshness').textContent='Refresh failed';$('freshness').dataset.relative='Refresh failed';$('freshness').closest('button').title=error?.message||'Live data refresh failed'}

const setupSteps=['Welcome','Dependencies','Sensors','Site & solar','Review'];
const setupKinds=[
['pv_power','Solar production',true],['load_power','Home load',true],['grid_power','Grid power',true],
['battery_power','Battery power',true],['battery_soc','Battery state of charge',true],
['battery_capacity','Usable battery capacity',false],['battery_cycles','Battery life cycles',false],
['battery_temperature','Battery temperature',false],['inverter_temperature','Inverter temperature',false]
];
let setupStep=0,setupDiscovery=null,setupSelection={entities:{}},setupBusy=false;
function setupStatusClass(status){return status==='ready'||status==='detected'?'ready':status==='missing'||status==='incompatible'||status==='not_detected'?'missing':'warning'}
function setupProgress(){return setupSteps.map((_,index)=>`<span class="${index<setupStep?'complete':index===setupStep?'active':''}"></span>`).join('')}
function setupCheck(title,status,detail,action=''){const cls=setupStatusClass(status),icon=cls==='ready'?'✓':cls==='missing'?'!':'?';return `<div class="setup-check ${cls}"><span class="setup-check-icon">${icon}</span><div><strong>${esc(title)}</strong><small>${esc(detail)}</small></div>${action}</div>`}
function setupOption(candidate,selected){const label=`${candidate.friendly_name} · ${candidate.entity_id}${candidate.unit?' · '+candidate.unit:''}`;return `<option value="${esc(candidate.entity_id)}" ${candidate.entity_id===selected?'selected':''}>${esc(label)}</option>`}
function initializeSetupSelection(){
 const configured={
 pv_power:cfg?.power_connector?.pv_power_entity,load_power:cfg?.power_connector?.load_power_entity,
 grid_power:cfg?.power_connector?.grid_power_entity,battery_power:cfg?.battery_connector?.power_entity,
 battery_soc:cfg?.battery_connector?.soc_entity,battery_capacity:cfg?.battery_connector?.capacity_entity,
 battery_cycles:cfg?.battery_connector?.cycle_count_entity,battery_temperature:cfg?.battery_connector?.temperature_entity,
 inverter_temperature:cfg?.power_connector?.inverter_temperature_entity
 };
 setupKinds.forEach(([kind])=>{const candidates=setupDiscovery?.entities?.[kind]||[],existing=configured[kind];setupSelection.entities[kind]=candidates.some(c=>c.entity_id===existing)?existing:(candidates[0]?.entity_id||'')});
 const prices=setupDiscovery?.price_entities||[],weather=setupDiscovery?.weather_entities||[];
 setupSelection.price_entity=prices.some(c=>c.entity_id===cfg?.price_connector?.entity)?cfg.price_connector.entity:(prices.find(c=>c.compatible)?.entity_id||'');
 setupSelection.weather_entity=weather.some(c=>c.entity_id===cfg?.forecast_connector?.weather_entity)?cfg.forecast_connector.weather_entity:(weather[0]?.entity_id||'');
 const firstSetup=!cfg?.setup?.completed;
 setupSelection.site={
 timezone:(firstSetup?setupDiscovery?.home_assistant?.timezone:cfg?.site?.timezone)||cfg?.site?.timezone||'Europe/Tallinn',
 country:(firstSetup?setupDiscovery?.home_assistant?.country:cfg?.site?.country)||cfg?.site?.country||'EE',
 currency:(firstSetup?setupDiscovery?.home_assistant?.currency:cfg?.site?.currency)||cfg?.site?.currency||'EUR'
 };
 setupSelection.solar={
 peak_kw:cfg?.forecast_connector?.solar_peak_kw??25.48,
 tilt_degrees:cfg?.forecast_connector?.solar_tilt_degrees??22,
 azimuth_degrees:cfg?.forecast_connector?.solar_azimuth_degrees??180
 };
 const q=setupDiscovery?.qilowatt||{},qcfg=cfg?.qilowatt||{};
 setupSelection.qilowatt={
 mode:qcfg.mode||'disabled',
 mode_entity:qcfg.mode_entity||q.entities?.mode||'',
 source_entity:qcfg.source_entity||q.entities?.source||'',
 power_limit_entity:qcfg.power_limit_entity||q.entities?.power_limit||'',
 connected_entity:qcfg.connected_entity||q.entities?.connected||''
 };
 setupSelection.manual_capacity_kwh=cfg?.battery_connector?.capacity_source==='manual_override'?cfg.battery_connector.manual_capacity_kwh:'';
}
function renderSetupWelcome(){
 const ha=setupDiscovery.home_assistant;
 return `<div class="setup-intro"><div class="setup-panel"><h3>A clean start, without vendor-specific names</h3><p>Energy Pilot identifies sensors by meaning, unit and Home Assistant metadata. A renamed entity such as <code>sensor.elektrijaam_total_battery_life_cycles</code> works just like its original Deye name.</p></div><div class="setup-checks">${setupCheck('Home Assistant API',ha.connected?'ready':'missing',ha.connected?`${ha.entity_count} entities available`:'The add-on cannot read Home Assistant entities')}${setupCheck('Home location',ha.location_available?'ready':'missing',ha.location_available?`${ha.timezone||'Timezone detected'} · ${ha.country||'country detected'}`:(ha.location_error||'Location metadata is unavailable'))}</div></div>`;
}
function renderSetupDependencies(){
 const deps=setupDiscovery.dependencies,prices=setupDiscovery.price_entities||[],weather=setupDiscovery.weather_entities||[];
 const q=setupDiscovery.qilowatt||{},qmode=setupSelection.qilowatt?.mode||'disabled';
 const priceOptions=prices.map(candidate=>`<option value="${esc(candidate.entity_id)}" ${candidate.entity_id===setupSelection.price_entity?'selected':''} ${candidate.compatible?'':'disabled'}>${esc(candidate.friendly_name)} · ${candidate.slot_count_today} slots${candidate.compatible?'':' · incompatible'}</option>`).join('');
 const weatherOptions=weather.map(candidate=>`<option value="${esc(candidate.entity_id)}" ${candidate.entity_id===setupSelection.weather_entity?'selected':''}>${esc(candidate.friendly_name)} · ${esc(candidate.entity_id)}</option>`).join('');
 return `<div class="setup-checks">
 ${setupCheck('HACS',deps.hacs.status,deps.hacs.status==='detected'?'HACS is available.':'Install HACS before adding the required community Nord Pool integration.',`<a href="${deps.hacs.url}" target="_blank" rel="noreferrer">Instructions ↗</a>`)}
 ${setupCheck('HACS Nord Pool',deps.nordpool_hacs.status,deps.nordpool_hacs.note,`<a href="${deps.nordpool_hacs.repository}" target="_blank" rel="noreferrer">Repository ↗</a>`)}
 <div class="setup-panel"><strong>Nord Pool installation steps</strong><ol class="setup-steps"><li>Install HACS if it is not already available.</li><li>In HACS, open Integrations and install <strong>Nord Pool</strong> from <code>custom-components/nordpool</code>.</li><li>Restart Home Assistant, then add the Nord Pool integration under Devices &amp; services.</li><li>Return here and choose Re-scan. Energy Pilot verifies the required today and tomorrow slots.</li></ol><small class="setup-help">Energy Pilot cannot silently install or restart Home Assistant integrations. The wizard verifies every step and continues from the same screen.</small></div>
 <div class="setup-panel"><div class="field"><label>Compatible Nord Pool price source</label><select id="setupPriceEntity" class="planner-range"><option value="">Choose a compatible sensor…</option>${priceOptions}</select><small class="setup-help">The official Home Assistant integration is not accepted unless it exposes timestamped today and tomorrow slots. Energy Pilot expects the HACS custom integration.</small></div></div>
 ${setupCheck('Hourly weather forecast',deps.weather.status,deps.weather.note)}
 <div class="setup-panel"><div class="field"><label>Weather entity</label><select id="setupWeatherEntity" class="planner-range"><option value="">Choose a weather entity…</option>${weatherOptions}</select><small class="setup-help">If none is available, add an hourly-forecast weather integration under Home Assistant → Settings → Devices & services.</small></div></div>
 ${setupCheck('Qilowatt (optional)',deps.qilowatt_ha?.status||'optional',deps.qilowatt_ha?.note||'Optional external dispatch integration.',`<a href="${deps.qilowatt_ha?.repository||'https://github.com/qilowatt/qilowatt-ha'}" target="_blank" rel="noreferrer">Repository ↗</a>`)}
 <div class="setup-panel"><div class="field"><label>Qilowatt operating mode</label><select id="setupQilowattMode" class="planner-range"><option value="disabled" ${qmode==='disabled'?'selected':''}>Disabled</option><option value="ha_dispatch" ${qmode==='ha_dispatch'?'selected':''}>Home Assistant / MQTT dispatch</option></select><small class="setup-help">${q.entities_found||0} of 4 dispatch entities detected. HA/MQTT mode reads Qilowatt desired-state entities and prioritizes fusebox / Kratt mFRR commands.</small></div></div>
 </div>`;
}
function renderSetupSensors(){
 return `<div class="setup-sensors">${setupKinds.map(([kind,label,required])=>{const candidates=setupDiscovery.entities?.[kind]||[],selected=setupSelection.entities[kind]||'',best=candidates[0],status=!candidates.length?'missing':best?.ambiguous?'confirm':'ready';return `<div class="setup-sensor-row"><div><strong>${esc(label)}${required?' *':''}</strong><small>${required?'Required':'Optional'}</small></div><select class="planner-range" data-setup-kind="${kind}"><option value="">${required?'Choose a sensor…':'Not used'}</option>${candidates.map(candidate=>setupOption(candidate,selected)).join('')}</select><span class="setup-status ${status==='ready'?'':status}">${status==='ready'?'Detected':status==='confirm'?'Confirm':'Missing'}</span></div>`}).join('')}</div><small class="setup-help">A yellow “Confirm” means multiple equally plausible sensors were found. Choose the one that belongs to this inverter.</small>`;
}
function renderSetupSite(){
 const site=setupSelection.site,solar=setupSelection.solar;
 return `<div class="setup-form"><div class="field"><label>Timezone</label><input id="setupTimezone" value="${esc(site.timezone)}"></div><div class="field"><label>Country</label><input id="setupCountry" maxlength="2" value="${esc(site.country)}"></div><div class="field"><label>Currency</label><input id="setupCurrency" maxlength="3" value="${esc(site.currency)}"></div><div class="field"><label>Manual usable capacity (kWh, optional)</label><input id="setupManualCapacity" type="number" min=".1" step=".01" value="${esc(setupSelection.manual_capacity_kwh)}"><small class="setup-help">Use only when no reliable capacity sensor exists.</small></div><div class="field"><label>Solar array peak power (kWp)</label><input id="setupSolarPeak" type="number" min=".1" step=".01" value="${esc(solar.peak_kw)}"></div><div class="field"><label>Panel tilt (°)</label><input id="setupSolarTilt" type="number" min="0" max="90" step="1" value="${esc(solar.tilt_degrees)}"></div><div class="field"><label>Panel azimuth (°)</label><input id="setupSolarAzimuth" type="number" min="0" max="360" step="1" value="${esc(solar.azimuth_degrees)}"></div><div class="setup-panel wide"><strong>Safe first run</strong><p>Energy Pilot starts in Simulation mode. No inverter commands are sent during onboarding.</p></div></div>`;
}
function renderSetupReview(){
 const rows=setupKinds.filter(([kind,,required])=>required||setupSelection.entities[kind]).map(([kind,label])=>`<div class="setup-review-row"><span>${esc(label)}</span><strong>${esc(setupSelection.entities[kind]||'Not selected')}</strong></div>`).join('');
 const qmode=setupSelection.qilowatt?.mode||'disabled',qlabel=qmode==='ha_dispatch'?'HA / MQTT dispatch':'Disabled';
 return `<div class="setup-review">${rows}<div class="setup-review-row"><span>Nord Pool</span><strong>${esc(setupSelection.price_entity||'Missing')}</strong></div><div class="setup-review-row"><span>Weather</span><strong>${esc(setupSelection.weather_entity||'Missing')}</strong></div><div class="setup-review-row"><span>Qilowatt</span><strong>${esc(qlabel)}</strong></div><div class="setup-review-row"><span>Solar array</span><strong>${Number(setupSelection.solar.peak_kw).toFixed(2)} kWp · ${Number(setupSelection.solar.tilt_degrees).toFixed(0)}° / ${Number(setupSelection.solar.azimuth_degrees).toFixed(0)}°</strong></div><div class="setup-panel"><strong>Ready to build the first plan</strong><p>Finish saves these entity choices and initial settings. You can re-run this wizard from Settings at any time.</p></div></div>`;
}
function captureSetupStep(){
 if(setupStep===1){setupSelection.price_entity=$('setupPriceEntity')?.value||'';setupSelection.weather_entity=$('setupWeatherEntity')?.value||'';setupSelection.qilowatt.mode=$('setupQilowattMode')?.value||'disabled'}
 if(setupStep===2)document.querySelectorAll('[data-setup-kind]').forEach(select=>setupSelection.entities[select.dataset.setupKind]=select.value);
 if(setupStep===3){setupSelection.site={timezone:$('setupTimezone').value.trim(),country:$('setupCountry').value.trim().toUpperCase(),currency:$('setupCurrency').value.trim().toUpperCase()};setupSelection.solar={peak_kw:Number($('setupSolarPeak').value),tilt_degrees:Number($('setupSolarTilt').value),azimuth_degrees:Number($('setupSolarAzimuth').value)};setupSelection.manual_capacity_kwh=$('setupManualCapacity').value===''?'':Number($('setupManualCapacity').value)}
}
function validateSetupStep(){
 captureSetupStep();
 if(setupStep===0&&!setupDiscovery.home_assistant.connected)return 'Energy Pilot must be able to read the Home Assistant API.';
 if(setupStep===1){if(!setupSelection.price_entity)return 'Install or select the compatible HACS Nord Pool sensor.';if(!setupSelection.weather_entity)return 'Install or select an hourly weather entity.'}
 if(setupStep===2){const missing=setupKinds.filter(([kind,,required])=>required&&!setupSelection.entities[kind]).map(([,label])=>label);if(missing.length)return `Choose: ${missing.join(', ')}.`}
 if(setupStep===3){if(!setupSelection.entities.battery_capacity&&!setupSelection.manual_capacity_kwh)return 'Choose a battery capacity sensor or enter manual usable capacity.';if(!setupSelection.site.timezone||setupSelection.site.country.length!==2||setupSelection.site.currency.length!==3)return 'Check timezone, country and currency.';if(!(setupSelection.solar.peak_kw>0))return 'Enter the solar array peak power.'}
 return '';
}
function renderSetup(){
 $('setupProgress').innerHTML=setupProgress();$('setupBack').disabled=setupStep===0;$('setupRescan').classList.toggle('hidden',setupStep>2);$('setupNext').textContent=setupStep===setupSteps.length-1?'Finish setup':'Continue';
 $('setupSubtitle').textContent=[`Step 1 of ${setupSteps.length} · Verify the connection.`,`Step 2 of ${setupSteps.length} · Install and verify required integrations.`,`Step 3 of ${setupSteps.length} · Confirm automatically detected sensors.`,`Step 4 of ${setupSteps.length} · Add the few values Home Assistant cannot infer.`,`Step 5 of ${setupSteps.length} · Review the initial configuration.`][setupStep];
 $('setupBody').innerHTML=[renderSetupWelcome,renderSetupDependencies,renderSetupSensors,renderSetupSite,renderSetupReview][setupStep]();
}
async function scanSetup(force=false){
 setupBusy=true;$('setupBody').innerHTML=`<span class="loading-indicator centered"><i class="loading-spinner" aria-hidden="true"></i><span>Scanning Home Assistant</span></span>`;$('setupNext').disabled=true;$('setupRescan').disabled=true;
 try{const response=await fetch(`api/setup/discovery${force?'?rescan=true':''}`),data=await response.json();if(!response.ok)throw Error(data.detail||'Discovery failed');setupDiscovery=data;initializeSetupSelection();renderSetup()}
 catch(error){$('setupBody').innerHTML=`<div class="setup-error">${esc(error.message)}</div>`}
 finally{setupBusy=false;$('setupNext').disabled=false;$('setupRescan').disabled=false}
}
async function openSetupWizard(force=false){setupStep=0;$('setupBackdrop').classList.add('open');$('setupBackdrop').setAttribute('aria-hidden','false');$('setupClose').classList.toggle('hidden',!cfg?.setup?.completed);await scanSetup(force)}
function closeSetupWizard(){if(!cfg?.setup?.completed)return;$('setupBackdrop').classList.remove('open');$('setupBackdrop').setAttribute('aria-hidden','true')}
async function finishSetup(){
 setupBusy=true;$('setupNext').disabled=true;$('setupNext').textContent='Saving…';
 try{const body={...setupSelection,manual_capacity_kwh:setupSelection.manual_capacity_kwh===''?null:setupSelection.manual_capacity_kwh},response=await fetch('api/setup/complete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),data=await response.json();if(!response.ok)throw Error(data.detail||'Setup could not be completed');await loadConfig();$('setupBackdrop').classList.remove('open');$('setupBackdrop').setAttribute('aria-hidden','true');notice.textContent='Installation setup completed.';await loadOverview()}
 catch(error){$('setupBody').insertAdjacentHTML('beforeend',`<div class="setup-error">${esc(error.message)}</div>`)}
 finally{setupBusy=false;$('setupNext').disabled=false;$('setupNext').textContent='Finish setup'}
}
$('setupBack').onclick=()=>{if(setupBusy||setupStep===0)return;captureSetupStep();setupStep--;renderSetup()};
$('setupNext').onclick=async()=>{if(setupBusy)return;const error=validateSetupStep();if(error){$('setupBody').insertAdjacentHTML('beforeend',`<div class="setup-error">${esc(error)}</div>`);return}if(setupStep===setupSteps.length-1){await finishSetup();return}setupStep++;renderSetup()};
$('setupRescan').onclick=()=>scanSetup(true);$('setupClose').onclick=closeSetupWizard;$('setupWizardButton').onclick=()=>openSetupWizard(true);
async function start(){try{await loadConfig();if(!cfg?.setup?.completed){await openSetupWizard(true);return}await loadOverview()}catch(e){notice.textContent=e.message;$('flowRoutes').innerHTML='<span class="route-chip">Live routes unavailable</span>';showRefreshFailure(e)}}start();setInterval(()=>{if(cfg?.setup?.completed)loadOverview().catch(showRefreshFailure)},5000);
